categories = %w[Супы Завтраки Выпечка].index_with do |name|
  Category.find_or_create_by!(name: name)
end

recipes = [
  { title: "Овощной суп", category: "Супы", cooking_time: 40, difficulty: "Легко", image_url: "/images/recipes/vegetable-soup.png", description: "Лёгкий суп с картофелем, морковью и сезонными овощами.", instructions: "Вымойте овощи, очистите картофель и морковь.\nНарежьте картофель и кабачок небольшими кубиками, лук мелко порубите.\nРазогрейте кастрюлю с ложкой масла и обжарьте лук до мягкости.\nДобавьте морковь, перемешайте и готовьте ещё 3 минуты.\nВлейте горячую воду, положите картофель и доведите суп до кипения.\nЧерез 10 минут добавьте кабачок, посолите и варите до мягкости овощей.\nСнимите с огня, добавьте зелень и оставьте под крышкой на 5 минут.", ingredients: { "Картофель" => "3 шт.", "Морковь" => "1 шт.", "Лук" => "1 шт.", "Кабачок" => "1 шт." } },
  { title: "Куриный суп", category: "Супы", cooking_time: 55, difficulty: "Легко", image_url: "/images/recipes/chicken-soup.png", description: "Домашний куриный суп с лапшой и свежей зеленью.", instructions: "Промойте куриное филе, залейте холодной водой и поставьте на средний огонь.\nПосле закипания снимите пену, уменьшите огонь и варите филе 25 минут.\nДостаньте готовую курицу, немного остудите и разберите на волокна.\nОчистите картофель и морковь, нарежьте их небольшими кусочками.\nПоложите овощи в бульон и варите 12–15 минут.\nДобавьте лапшу и куриное мясо, посолите по вкусу.\nЧерез 7 минут выключите огонь, добавьте укроп и дайте супу настояться под крышкой.", ingredients: { "Куриное филе" => "300 г", "Картофель" => "2 шт.", "Морковь" => "1 шт.", "Лапша" => "100 г" } },
  { title: "Сырники", category: "Завтраки", cooking_time: 25, difficulty: "Легко", image_url: "/images/recipes/syrniki.png", description: "Нежные сырники из творога с румяной корочкой.", instructions: "Переложите творог в миску и разомните вилкой до однородности.\nДобавьте яйцо и сахар, тщательно перемешайте.\nВсыпьте большую часть муки и соберите мягкое тесто.\nПрисыпьте рабочую поверхность оставшейся мукой.\nСформируйте из теста колбаску, разделите её на части и сделайте небольшие шайбы.\nРазогрейте сковороду с небольшим количеством масла.\nЖарьте сырники на среднем огне по 3–4 минуты с каждой стороны до золотистой корочки.\nПодавайте тёплыми со сметаной или ягодами.", ingredients: { "Творог" => "500 г", "Яйцо" => "1 шт.", "Мука" => "100 г", "Сахар" => "2 ст. л." } },
  { title: "Омлет с овощами", category: "Завтраки", cooking_time: 20, difficulty: "Легко", image_url: "/images/recipes/omelette.png", description: "Быстрый омлет с томатами, сладким перцем и зеленью.", instructions: "Вымойте помидор и сладкий перец, удалите у перца семена.\nНарежьте овощи небольшими кубиками.\nРазогрейте сковороду с каплей масла и обжарьте перец 2 минуты.\nДобавьте помидор и готовьте ещё минуту, чтобы он стал мягче.\nВ миске взбейте яйца с молоком, солью и щепоткой перца.\nВлейте смесь к овощам и аккуратно распределите её по сковороде.\nНакройте крышкой и готовьте на слабом огне 5–6 минут.\nПосыпьте готовый омлет зеленью и подавайте сразу.", ingredients: { "Яйцо" => "3 шт.", "Молоко" => "50 мл", "Помидор" => "1 шт.", "Сладкий перец" => "1/2 шт." } },
  { title: "Яблочный пирог", category: "Выпечка", cooking_time: 70, difficulty: "Средне", image_url: "/images/recipes/apple-pie.png", description: "Простой ароматный пирог с яблоками и корицей.", instructions: "Разогрейте духовку до 180 °C и подготовьте форму для выпечки.\nЯблоки вымойте, удалите сердцевины и нарежьте тонкими ломтиками.\nВзбейте яйца с сахаром до светлой пышной массы.\nПросейте муку и аккуратно вмешайте её в яичную смесь.\nДобавьте щепотку корицы и перемешайте тесто до однородности.\nВыложите половину яблок в форму, распределите сверху тесто.\nРазложите оставшиеся яблоки и слегка утопите их в тесте.\nВыпекайте 40–45 минут, затем остудите пирог в форме перед подачей.", ingredients: { "Яблоки" => "4 шт.", "Яйцо" => "2 шт.", "Мука" => "180 г", "Сахар" => "120 г" } },
  { title: "Блины", category: "Выпечка", cooking_time: 35, difficulty: "Легко", image_url: "/images/recipes/blini.png", description: "Тонкие домашние блины для завтрака или чаепития.", instructions: "Достаньте яйца и молоко заранее, чтобы они стали комнатной температуры.\nВ глубокой миске взбейте яйца с сахаром и щепоткой соли.\nВлейте примерно половину молока и перемешайте венчиком.\nПостепенно добавьте просеянную муку, разбивая все комочки.\nВлейте оставшееся молоко и дайте тесту постоять 10 минут.\nХорошо разогрейте сковороду и смажьте её тонким слоем масла.\nНаливайте тесто небольшими порциями, поворачивая сковороду для тонкого слоя.\nЖарьте каждый блин до румяности с обеих сторон и складывайте стопкой.", ingredients: { "Мука" => "200 г", "Молоко" => "500 мл", "Яйцо" => "2 шт.", "Сахар" => "1 ст. л." } },
  { title: "Томатный суп", category: "Супы", cooking_time: 35, difficulty: "Легко", image_url: "/images/recipes/tomato-soup.png", description: "Яркий томатный суп с овощами и ароматными травами.", instructions: "Нарежьте лук, морковь и сладкий перец небольшими кубиками.\nРазогрейте в кастрюле масло и обжарьте лук до мягкости.\nДобавьте морковь и перец, готовьте ещё 4 минуты.\nВлейте протёртые томаты и овощной бульон.\nДоведите суп до кипения, посолите и добавьте сушёные травы.\nВарите на слабом огне 20 минут.\nПодавайте суп горячим со свежей зеленью.", ingredients: { "Протёртые томаты" => "500 г", "Овощной бульон" => "500 мл", "Лук" => "1 шт.", "Морковь" => "1 шт." } },
  { title: "Грибной крем-суп", category: "Супы", cooking_time: 45, difficulty: "Средне", image_url: "/images/recipes/mushroom-cream-soup.png", description: "Нежный крем-суп из шампиньонов со сливочным вкусом.", instructions: "Нарежьте шампиньоны, лук и картофель.\nОбжарьте лук на масле до прозрачности.\nДобавьте грибы и готовьте, пока не выпарится лишняя влага.\nПоложите картофель, влейте бульон и доведите до кипения.\nВарите 20 минут до мягкости картофеля.\nДобавьте сливки и пробейте суп блендером до кремовой текстуры.\nПрогрейте ещё минуту и подавайте.", ingredients: { "Шампиньоны" => "400 г", "Картофель" => "2 шт.", "Сливки" => "150 мл", "Овощной бульон" => "600 мл" } },
  { title: "Овсяная каша с ягодами", category: "Завтраки", cooking_time: 15, difficulty: "Легко", image_url: "/images/recipes/oatmeal-berries.png", description: "Тёплая овсяная каша с ягодами для спокойного утра.", instructions: "Влейте молоко в небольшую кастрюлю и доведите до лёгкого кипения.\nДобавьте овсяные хлопья и щепотку соли.\nВарите на слабом огне, помешивая, 5–7 минут.\nСнимите кашу с огня и дайте ей постоять под крышкой 2 минуты.\nРазложите кашу по тарелкам.\nДобавьте ягоды и мёд перед подачей.", ingredients: { "Овсяные хлопья" => "80 г", "Молоко" => "300 мл", "Ягоды" => "100 г", "Мёд" => "1 ст. л." } },
  { title: "Тосты с авокадо", category: "Завтраки", cooking_time: 15, difficulty: "Легко", image_url: "/images/recipes/avocado-toast.png", description: "Хрустящие тосты с кремовым авокадо и яйцом.", instructions: "Подсушите хлеб в тостере или на сухой сковороде.\nРазрежьте авокадо, удалите косточку и переложите мякоть в миску.\nРазомните авокадо вилкой, добавьте лимонный сок и соль.\nСварите яйца до желаемой степени готовности.\nРаспределите авокадо по тостам.\nСверху выложите яйца и посыпьте перцем.", ingredients: { "Хлеб для тостов" => "2 ломтика", "Авокадо" => "1 шт.", "Яйцо" => "2 шт.", "Лимонный сок" => "1 ч. л." } },
  { title: "Творожная запеканка", category: "Выпечка", cooking_time: 60, difficulty: "Легко", image_url: "/images/recipes/cottage-cheese-casserole.png", description: "Воздушная творожная запеканка для семейного чаепития.", instructions: "Разогрейте духовку до 180 °C и смажьте форму маслом.\nСмешайте творог, яйца, сахар и сметану до однородности.\nДобавьте манную крупу и оставьте массу на 10 минут.\nПереложите творожную массу в форму.\nРазровняйте поверхность ложкой.\nВыпекайте 40–45 минут до золотистого верха.\nОстудите запеканку в форме и нарежьте порциями.", ingredients: { "Творог" => "500 г", "Яйцо" => "2 шт.", "Сметана" => "100 г", "Манная крупа" => "3 ст. л." } },
  { title: "Банановые маффины", category: "Выпечка", cooking_time: 40, difficulty: "Легко", image_url: "/images/recipes/banana-muffins.png", description: "Мягкие маффины с бананом и лёгким ароматом корицы.", instructions: "Разогрейте духовку до 180 °C и подготовьте формочки для маффинов.\nРазомните бананы вилкой до пюре.\nСмешайте яйца, сахар и растопленное масло.\nДобавьте банановое пюре и перемешайте.\nВсыпьте муку, разрыхлитель и корицу.\nРаспределите тесто по формочкам, заполняя их на две трети.\nВыпекайте 22–25 минут и остудите на решётке.", ingredients: { "Бананы" => "2 шт.", "Мука" => "180 г", "Яйцо" => "1 шт.", "Разрыхлитель" => "1 ч. л." } }
]

recipes.each do |data|
  recipe = Recipe.find_or_initialize_by(title: data[:title])
  recipe.assign_attributes(category: categories.fetch(data[:category]), cooking_time: data[:cooking_time], difficulty: data[:difficulty], image_url: data[:image_url], description: data[:description], instructions: data[:instructions])
  recipe.save!
  recipe.recipe_ingredients.destroy_all

  data[:ingredients].each do |name, quantity|
    ingredient = Ingredient.find_or_create_by!(name: name)
    recipe.recipe_ingredients.create!(ingredient: ingredient, quantity: quantity)
  end
end
